),
grp as (select raw.d::date as d, g.n as gi, g.t from raw cross join lateral regexp_split_to_table(raw.s, '\|?@') with ordinality as g(t, n) where g.t <> ''),
rw as (select grp.d, grp.gi, r.n as ri, split_part(grp.t, '|', 1) as hdr, r.t as item from grp cross join lateral regexp_split_to_table(grp.t, '\|') with ordinality as r(t, n) where r.n > 1)
insert into public.milk_ack_history (dairy_unit_id, ack_date, seq, shift, kind, route, milk_type, team, bmc_code, bmc_name, dest, tanker, inv_no, qty_litres, fat_pct, snf_pct, ack_litres, ack_fat_pct, ack_snf_pct)
select (select min(dairy_unit_id) from public.bmcs where kind = 'BMC' and cc_code is not null),
  rw.d, rw.gi * 1000 + rw.ri,
  case split_part(item, ':', 2) when 'M' then 'MOR' when 'E' then 'EVE' when 'X' then 'EVE/MOR' else '' end,
  coalesce(nm.kind, 'BMC'), split_part(hdr, '~', 1), 'RCM', coalesce(nm.team, ''), split_part(item, ':', 1)::int, coalesce(nm.name, ''),
  split_part(hdr, '~', 3), split_part(hdr, '~', 2), split_part(item, ':', 3),
  split_part(item, ':', 4)::numeric, split_part(item, ':', 5)::numeric, split_part(item, ':', 6)::numeric,
  nullif(split_part(item, ':', 7), '')::numeric, nullif(split_part(item, ':', 8), '')::numeric, nullif(split_part(item, ':', 9), '')::numeric
from rw left join nm on nm.code = split_part(item, ':', 1)::int
on conflict (dairy_unit_id, ack_date, seq) do nothing;
